def totals(rows):
    low = sum(q * lo for _, _, q, _, lo, hi, _ in rows)
    high = sum(q * hi for _, _, q, _, lo, hi, _ in rows)
    return low, high, round(low * .15), round(high * .15), round(low * 1.15), round(high * 1.15)

def money(n): return f'${n:,.0f}'
AL, AH, ACL, ACH, ATL, ATH = totals(AUSTIN)
BL, BH, BCL, BCH, BTL, BTH = totals(BOSTON)

FONT = TTFont(OUT / 'fonts/big-shoulders-900.ttf')
BODYFONT = TTFont(OUT / 'fonts/archivo-700.ttf')
def vector_text(text, x, baseline, size, font=FONT, color=INK, spacing=0, stroke=None):
    glyphs, cmap = font.getGlyphSet(), font.getBestCmap()
    units = font['head'].unitsPerEm
    scale = size / units
    parts=[]
    cursor=x
    for char in text:
        name=cmap.get(ord(char),'.notdef')
        pen=SVGPathPen(glyphs)
        glyphs[name].draw(TransformPen(pen,(scale,0,0,-scale,cursor,baseline)))
        parts.append(pen.getCommands())
        cursor += glyphs[name].width * scale + spacing
    attrs = f' fill="{color}"'
    if stroke: attrs += f' stroke="{stroke}" stroke-width="3" paint-order="stroke fill" stroke-linejoin="round"'
    return f'<path{attrs} d="{" ".join(parts)}"/>', cursor-x-spacing

def line_width(text,size,font=FONT,spacing=0):
    return vector_text(text,0,0,size,font,spacing=spacing)[1]

logo_source=(ART/'official-logo-1.svg').read_text()
logo_inner=re.search(r'<svg[^>]*>(.*)</svg>',logo_source,re.S)[1].replace('currentColor',INK)
def wordmark(x,y,width,color=INK):
    return f'<g transform="translate({x} {y}) scale({width/1164})">{logo_inner.replace(INK,color)}</g>'

def typography(city):
    # At 48 × 14 ft: 3000 × 875 coordinate system. Typography is real vector
    # geometry; every word survives with the glow removed.
    parts=['<defs><filter id="glow" x="-8%" y="-12%" width="116%" height="124%"><feGaussianBlur stdDeviation="5"/></filter></defs>']
    parts.append(wordmark(764,64,900))
    lines=city['lines']
    size=min(city['size'], min(1390/line_width(line,1) for line in lines))
    start=425 if len(lines)==2 else 350
    step=210 if len(lines)==2 else 158
    for i,line in enumerate(lines):
        x=764
        baseline=start+i*step
        path,_=vector_text(line,x,baseline,size,color=ORANGE,stroke=INK)
        parts.append(f'<g opacity=".38" filter="url(#glow)">{path}</g>')
        parts.append(path)
    cta=city.get('cta','BUILD WITH US IN TEXAS')
    cta_size=min(58,1390/line_width(cta,1,BODYFONT,0))
    parts.append(vector_text(cta,764,733,cta_size,BODYFONT,color=INK)[0])
    parts.append(vector_text('TERRAFIRMA.INC',764,810,58,BODYFONT,color=INK,spacing=2)[0])
    return ''.join(parts)

def svg_doc(body,title):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 3000 875" role="img"><title>{escape(title)}</title>{body}</svg>'

for city in CITIES:
    title=f"TerraFirma — {city['name']}: {' '.join(city['lines'])} {city.get('cta','Build with us in Texas')}. terrafirma.inc"
    type_svg=typography(city)
    (ART/f"type-{city['id']}.svg").write_text(svg_doc(type_svg,title))
    bg=base64.b64encode((ART/f"{city['family']}-background.png").read_bytes()).decode()
    full=f'<image x="0" y="-62.5" width="3000" height="1000" href="data:image/png;base64,{bg}"/>{type_svg}'
    (DL/f"billboard-{city['id']}.svg").write_text(svg_doc(full,title))

CSV_HEAD=['Scenario','Category','Line item','Quantity','Unit','Unit low USD','Unit high USD','Extended low USD','Extended high USD','Basis / owner']
csv_out=io.StringIO()
writer=csv.writer(csv_out, lineterminator='\n')
writer.writerow(CSV_HEAD)
for scenario,rows in [('Austin recommended pilot',AUSTIN),('Boston optional expansion',BOSTON)]:
    for cat,item,q,unit,lo,hi,owner in rows:
        writer.writerow([scenario,cat,item,q,unit,lo,hi,q*lo,q*hi,owner+'; planning allowance, not a quote'])
    lo,hi,cl,ch,tl,th=totals(rows)
    for label,a,b in [('Subtotal',lo,hi),('Contingency 15%',cl,ch),('TOTAL',tl,th)]:
        writer.writerow([scenario,label,'','','','','',a,b,'USD; no vendor commitments; internal payroll and owned assets excluded'])
