(OUT/'campaign-data.json').write_text(json.dumps({'version':VERSION,'cities':CITIES,'austin':AUSTIN,'boston':BOSTON,'contingency_rate':.15},indent=2)+'\n')

def board(city,download=True):
    ident=city['id']
    label=escape(f"{city['name']}: {' '.join(city['lines'])} {city.get('cta','Build with us in Texas')}. terrafirma.inc")
    content=f'<span class="billboard" role="img" aria-label="{label}"><img class="board-bg" src="img/v3/{city["family"]}-background.png" alt="" loading="lazy" width="2172" height="724"><img class="board-type" src="img/v3/type-{ident}.svg" alt="" loading="lazy" width="3000" height="875"></span>'
    if download: return f'<a class="board-link" href="downloads/billboard-{ident}.svg" target="_blank" rel="noopener" aria-label="Open full-size {escape(city["name"])} billboard">{content}</a>'
    return content

def budget_table(rows, show_totals=True, total_rows=None):
    head='<div class="table-scroll"><table><thead><tr><th>Line item / quantity</th><th>Low</th><th>High</th></tr></thead><tbody>'
    for cat,item,q,unit,lo,hi,owner in rows:
        head+=f'<tr><td><strong>{escape(item)}</strong><small>{q} {escape(unit)} · {money(lo)}–{money(hi)} each</small></td><td>{money(q*lo)}</td><td>{money(q*hi)}</td></tr>'
    lo,hi,cl,ch,tl,th=totals(total_rows or rows)
    if show_totals:
        for label,a,b in [('Subtotal',lo,hi),('Contingency · 15%',cl,ch),('Total planning envelope',tl,th)]:
            head+=f'<tr class="total"><td>{label}</td><td>{money(a)}</td><td>{money(b)}</td></tr>'
    return head+'</tbody></table></div>'

