PRINT_CSS='''@page{size:1440px 900px;margin:0}html,body{margin:0;background:#EFEBE4}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}.sheet{width:1440px;height:900px;padding:46px 64px 54px;position:relative;overflow:hidden;break-after:page;page-break-after:always}.sheet:last-child{break-after:auto;page-break-after:auto}.sheet-head{display:flex;justify-content:space-between;align-items:center;border-top:2px solid #14182A;padding-top:10px;margin-bottom:28px;font:12px ui-monospace,monospace;text-transform:uppercase;letter-spacing:.08em}.sheet h2{font-size:66px;margin-bottom:24px}.sheet h3{font-size:31px}.sheet p,.sheet li{font-size:17px;line-height:1.55}.sheet .lead{font-size:25px;line-height:1.4}.sheet .grid2{gap:40px}.sheet .grid3{gap:28px}.sheet .grid4{gap:28px}.sheet .callout{margin:20px 0;padding:15px 22px}.sheet .callout p{font-size:16px}.sheet .foot{position:absolute;bottom:24px;left:64px;right:64px;display:flex;justify-content:space-between;font-size:11px;color:#535968;border-top:1px solid #BDB7AC;padding-top:8px}.sheet .board-link{pointer-events:none}.sheet .billboard{margin-top:20px}.sheet .city-grid{margin-top:24px}.sheet .city-grid p,.sheet .city-grid dd{font-size:16px}.sheet small{font-size:11px}.sheet td{padding:9px 10px;font-size:14px}.sheet th{padding:9px 10px}.sheet .timeline{grid-template-columns:150px 1fr;gap:0 26px}.sheet .timeline dt,.sheet .timeline dd{padding:13px 0}.sheet .timeline p{font-size:16px}.sheet .timeline dt{font-size:15px}.sheet .metric b{font-size:48px}.sheet .metric p{font-size:15px}.sheet .status{font-size:12px}.sheet .note{font-size:13px}.sheet .compact p,.sheet .compact li{font-size:16px}.sheet .compact h2{font-size:60px}.sheet details{display:block}.sheet summary{display:none}.sheet ul{margin-bottom:14px}.sheet .palette{margin-top:16px}.sheet .palette span{min-height:60px}.sheet .sources{font-size:16px}.sheet .sources li{font-size:16px;margin-bottom:15px}.sheet .hero-art{margin-top:35px}.sheet .section-top{display:none}'''

def strip_details(s): return re.sub(r'<details>.*?</details>','',s,flags=re.S)
def page(title,body,n,total):
    return f'<article class="sheet"><div class="sheet-head"><span>TerraFirma / {title}</span><span>{VERSION}</span></div><div class="page-content">{body}</div><div class="foot"><span>Texas Born, Mars Bound. · Campaign proposal</span><span>{n:02d} / {total:02d}</span></div></article>'
cover='<h1 style="font-size:90px;margin:12px 0">Texas Born.<br><span style="color:#B44B1B">Mars Bound.</span></h1><p class="lead">A focused Austin pilot. A consistent national creative system.<br>A clear route from attention to qualified talent.</p>'+board(CITIES[0])+f'<p class="note" style="margin-top:16px">Austin planning envelope: {money(ATL)}–{money(ATH)}, including 15% contingency. No media or vendors booked.</p>'
pilot_print=pilot[:pilot.index('<div class="grid2"')]+ '<div class="callout"><p><strong>Release commitments in stages.</strong> Creative and recruiting journey: up to $32,000 within the total envelope. Media and event commitments follow written quotes, destination QA, operating approval, and the permit decision. Boston is a separate proposal after the Austin review.</p></div>'
pages=[('Recommendation',cover),('Brand story',story),('Austin pilot',pilot_print),('Creative system',strip_details(system))]
for c in CITIES:
    pages.append((c['name'],f'<div class="city-head"><h2 style="margin:0">{c["name"]}</h2><span class="status">{c["status"]}</span></div>'+board(c)+f'<div class="city-grid"><div><h3>{" ".join(c["lines"])}</h3><p>{c["reason"]}</p><p class="note">48:14 concept master · {c["family"].title()} character</p></div><div><p><strong>Audience:</strong> {c["role"]}</p><p><strong>Placement:</strong> {c["placement"]}</p><p><strong>Proof:</strong> {c["proof"]}</p></div></div>'))
pages.append(('Readability and production','<h2>Make every word count.</h2>'+re.search(r'<details><summary>Production and readability gates</summary>(.*?)</details>',system,re.S)[1]+'<div class="callout"><p>Solid orange type, dark edges, restrained outer glow. Every headline is outlined vector geometry. Confirm the actual sightline and vendor proof before production.</p></div>'))
exp_main=strip_details(experience).split('<div class="callout">')[0]
pages.append(('Field experience','<div class="compact">'+exp_main+'</div>'))
pages.append(('Operating plan','<h2>One controlled experience.</h2>'+re.search(r'<details><summary>.*?</summary>(.*?)</details>',experience,re.S)[1]+'<div class="callout"><p>One machine × 60 minutes ÷ six-minute slots × 70% availability = seven sessions per hour; 56 in eight hours. Rehearse and release only validated capacity.</p></div>'))
pages.append(('Austin budget / 1 of 2',f'<h2>{money(ATL)}–{money(ATH)}</h2><p class="note">Austin only · Planning allowances in USD, not quotes · Two faces / four weeks / one event day</p>'+budget_table(AUSTIN[:6],False)+'<p class="note" style="margin-top:20px">Continued on the next page. This page is part of the same Austin envelope.</p>'))
pages.append(('Austin budget / 2 of 2','<h2>Delivery and total envelope.</h2><p class="note">Remaining line items; totals include all 12 Austin budget lines across both pages.</p>'+budget_table(AUSTIN[6:],True,AUSTIN)))
budget_notes=budget[budget.index('<div class="grid2"'):budget.index('<details>')]
pages.append(('Budget basis','<h2>Know what the number covers.</h2>'+budget_notes+'<div class="callout"><p>The itemized CSV and this plan supersede the earlier Pilot / Core / Flagship recommendation. Maintain quote, deposit, and actuals records separately. All-in costs must be reforecast before contracting.</p></div>'))
pages.append(('Optional Boston budget / 1 of 2',f'<h2>Boston is a separate decision.</h2><p class="note">Additional {money(BTL)}–{money(BTH)} · Planning allowances, not quotes · No commitment before the Austin review</p>'+budget_table(BOSTON[:5],False)+'<p class="note" style="margin-top:20px">Continued on the next page. None of these costs is included in Austin.</p>'))
