def print_doc(pages,title):
    print_head=head.replace('<title>TerraFirma — Texas Born, Mars Bound</title>',f'<title>{title}</title>')
    content=''.join(page(t,b,i+1,len(pages)) for i,(t,b) in enumerate(pages))
    content=content.replace('href="downloads/', 'href="https://jacklesser.me/terrafirma_billboard_campaign/downloads/')
    return print_head.replace('</head>',f'<style>{PRINT_CSS}</style></head>')+'<body>'+content+'</body></html>'
(OUT/'print-full.html').write_text(print_doc(pages,'TerraFirma — Campaign plan'))
boards_pages=[('Billboard edition','<h1 style="font-size:86px;margin:12px 0 18px">Texas Born.<br><span style="color:#B44B1B">Mars Bound.</span></h1><p class="lead">Austin: recommended pilot. Boston: gated expansion.<br>Eight more cities: future creative concepts.</p>'+board(CITIES[0])+'<p class="note" style="margin-top:16px">Solid vector headlines with restrained neon. Creative masters require vendor-specific production proofs.</p>')]+pages[4:14]+[('Production notes','<h2>Readable at a glance.</h2>'+re.search(r'<details><summary>Production and readability gates</summary>(.*?)</details>',system,re.S)[1]+'<p class="note">Official TerraFirma identity. Illustrated Operator character. All boards use the existing company URL; the recruiting destination must be ready before launch.</p>')]
(OUT/'print-billboards.html').write_text(print_doc(boards_pages,'TerraFirma — Billboards edition'))
print(f'Built site, 10 SVG masters, budget CSV, {len(pages)}-page plan, and {len(boards_pages)}-page billboard edition.')
print(f'Austin: {money(ATL)}–{money(ATH)}. Boston additional: {money(BTL)}–{money(BTH)}.')
